




-- Handbook v1.14 remediation: distinct synthetic places and route geometry within Nanjing.
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'metrotranslated business textentrance' WHEN 1 THEN 'translated business texthotel' WHEN 2 THEN 'translated business textshop' WHEN 3 THEN 'translated business textcentertranslated business textcenter'
      WHEN 4 THEN 'translated business textshop' WHEN 5 THEN 'translated business textroom' WHEN 6 THEN 'printingservicepoint' WHEN 7 THEN 'taxitranslated business textpoint'
      WHEN 8 THEN 'translated business textstation' WHEN 9 THEN 'translated business textpoint' WHEN 10 THEN 'translated business text' WHEN 11 THEN 'translated business textshop'
      WHEN 12 THEN 'translated business textentrance' WHEN 13 THEN 'translated business textpoint' WHEN 14 THEN 'stationeryshop' WHEN 15 THEN 'translated business textareaservicecenter'
      ELSE '24 translated business textbeforetranslated business text' END AS place_type,
    CASE rowid % 19
      WHEN 0 THEN 'translated business text' WHEN 1 THEN 'translated business textroutehastranslated business textsegment' WHEN 2 THEN 'translated business text' WHEN 3 THEN 'translated business text'
      WHEN 4 THEN 'translated business textmetrotranslated business text' WHEN 5 THEN 'translated business textpersontranslated business text' WHEN 6 THEN 'translated business text' WHEN 7 THEN 'does not providetranslated business textitemcustody'
      WHEN 8 THEN 'translated business textpurchasetranslated business text' WHEN 9 THEN 'translated business textprintingservice' WHEN 10 THEN 'translated business textmayadjustmenttranslated business text' WHEN 11 THEN 'nonetranslated business text'
      WHEN 12 THEN 'translated business textforroutetranslated business text' WHEN 13 THEN 'translated business textexam office' WHEN 14 THEN 'translated business textforsynthetictranslated business textplace' WHEN 15 THEN 'translated business text'
      WHEN 16 THEN 'translated business textandexam siteentranceareatranslated business text' WHEN 17 THEN 'translated business textforbackuptranslated business textpoint' ELSE 'departurebeforetranslated business text' END AS place_scope
  FROM places WHERE place_id LIKE 'PLACE_INTERP_DIST_%'
)
UPDATE places
SET name=CASE rowid % 5
      WHEN 0 THEN (SELECT place_type || '｜' || place_scope FROM facts WHERE facts.rid=places.rowid)
      WHEN 1 THEN (SELECT place_scope || 'of' || place_type FROM facts WHERE facts.rid=places.rowid)
      WHEN 2 THEN (SELECT place_type || '（' || place_scope || '）' FROM facts WHERE facts.rid=places.rowid)
      WHEN 3 THEN (SELECT 'Nanjingplace：' || place_type || '；' || place_scope FROM facts WHERE facts.rid=places.rowid)
      ELSE (SELECT place_type || 'translated business textpoint，' || place_scope FROM facts WHERE facts.rid=places.rowid)
    END,
    category=CASE rowid % 8 WHEN 0 THEN 'transit' WHEN 1 THEN 'hotel' WHEN 2 THEN 'cafe' WHEN 3 THEN 'library' WHEN 4 THEN 'convenience_store' WHEN 5 THEN 'pharmacy' WHEN 6 THEN 'print_shop' ELSE 'landmark' END,
    hours_json=json_object('open',CASE rowid % 3 WHEN 0 THEN '06:30' WHEN 1 THEN '08:00' ELSE '09:00' END,'close',CASE rowid % 4 WHEN 0 THEN '18:00' WHEN 1 THEN '20:00' WHEN 2 THEN '22:00' ELSE '23:30' END,'synthetic',1),
    formatted=CASE rowid % 6 WHEN 0 THEN 'Nanjingtranslated business textareasynthetictranslated business textroad' WHEN 1 THEN 'Nanjingtranslated business textareasynthetictranslated business textroad' WHEN 2 THEN 'Nanjingtranslated business textareasynthetictranslated business textroad' WHEN 3 THEN 'Nanjingtranslated business textareasyntheticstationbeforeroad' WHEN 4 THEN 'Nanjingtranslated business textareasynthetictranslated business textroad' ELSE 'Nanjingtranslated business textareasynthetictranslated business textroad' END || '（translated business text）',
    place_id=replace(place_id,'PLACE_INTERP_DIST_','PLACE_INTERP_CONTEXT_')
WHERE place_id LIKE 'PLACE_INTERP_DIST_%';

UPDATE roads
SET name=CASE rowid
      WHEN 1 THEN 'Hexitranslated business textsegment' WHEN 2 THEN 'translated business textroadtranslated business textsegment' WHEN 3 THEN 'translated business textroad' WHEN 4 THEN 'translated business textsegment'
      WHEN 5 THEN 'translated business textroadtranslated business textsegment' WHEN 6 THEN 'translated business textsegment' WHEN 7 THEN 'translated business textroadtranslated business textsegment' WHEN 8 THEN 'translated business textentrancetranslated business textroad'
      WHEN 9 THEN 'translated business textroadtranslated business textsegment' WHEN 10 THEN 'translated business textroadtranslated business textsegment' WHEN 11 THEN 'translated business textroadtranslated business textsegment' WHEN 12 THEN 'translated business textroadtranslated business textsegment'
      WHEN 13 THEN 'translated business textsegment' WHEN 14 THEN 'translated business textitemtranslated business textroad' WHEN 15 THEN 'translated business textroadtranslated business textsegment' WHEN 16 THEN 'translated business textsegment'
      WHEN 17 THEN 'translated business textroadtranslated business textsegment' WHEN 18 THEN 'integritytranslated business textsegment' WHEN 19 THEN 'translated business textCNYroadtranslated business textsegment' ELSE 'Nanjing Southstationtranslated business textsegment' END,
    geom_json=json_array(
      json_array(31.98 + rowid*0.004,118.69 + rowid*0.006),
      json_array(31.985 + rowid*0.004,118.697 + rowid*0.006)
    );

UPDATE transit_stops
SET name=CASE rowid % 10
      WHEN 0 THEN 'Hexitranslated business textstation' WHEN 1 THEN 'translated business textareastation' WHEN 2 THEN 'translated business textareastation' WHEN 3 THEN 'translated business textstation'
      WHEN 4 THEN 'translated business textentrancestation' WHEN 5 THEN 'translated business textstation' WHEN 6 THEN 'Nanjing Southstationshuttlepoint' WHEN 7 THEN 'translated business textcentertranslated business textentrancestation'
      WHEN 8 THEN 'translated business textSouth Station' ELSE 'translated business textstation' END || '·' || CASE rowid % 3 WHEN 0 THEN 'translated business text' WHEN 1 THEN 'metrotranslated business text' ELSE 'translated business textshuttle' END;
